"""Sandbox lifecycle repair installer. Run only on the VM; no orders or service actions."""
import argparse, hashlib, json, os, shutil, subprocess, sys, tempfile, fcntl
from datetime import datetime, timezone
from pathlib import Path
FILES=json.loads(bytes.fromhex(''))
ORIGINALS=json.loads(bytes.fromhex(''))
HASHES=json.loads(bytes.fromhex(''))

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group()
    group.add_argument('--check',action='store_true')
    group.add_argument('--test',action='store_true')
    args=parser.parse_args()
    root=Path.cwd()
    if not (root/'backend/market_lab').is_dir():parser.error('Run from ~/RB-ITOS-AI')
    for relative,content in FILES.items():
        if hashlib.sha256(content.encode()).hexdigest()!=HASHES[relative]:
            raise SystemExit('PAYLOAD_HASH_MISMATCH:'+relative)
        if digest(root/relative) not in {ORIGINALS[relative],HASHES[relative]}:
            raise SystemExit('SOURCE_CHANGED_NO_FILES_WRITTEN:'+relative)
        if relative.endswith('.py'):compile(content,relative,'exec')
    print(json.dumps(dict(status='VALIDATED',files=list(FILES),orders_sent=False,tests_run=False)),flush=True)
    if args.check:return
    if args.test:
        with tempfile.TemporaryDirectory(prefix='hilega-lifecycle-tests-') as folder:
            stage=Path(folder)
            for relative,content in FILES.items():
                target=stage/'files'/relative;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
            tests=stage/'tests';tests.mkdir()
            (tests/'test_hilega_sandbox_lifecycle_display.py').write_text(FILES['tests/test_hilega_sandbox_lifecycle_display.py'])
            (tests/'conftest.py').write_text(
                'import sys\nfrom pathlib import Path\n'+
                'sys.path.insert(0, '+repr(str(root/'backend'))+')\n'+
                'import market_lab\n'+
                'market_lab.__path__.insert(0, '+repr(str(stage/'files/backend/market_lab'))+')\n')
            result=subprocess.run([sys.executable,'-m','pytest','-q',str(tests)],cwd=root)
            raise SystemExit(result.returncode)
    pid_file=root/'data/hilega-upstox-sandbox-worker.pid'
    if pid_file.exists():
        try:pid=int(pid_file.read_text().strip())
        except ValueError:raise SystemExit('INVALID_WORKER_PID_FILE')
        if pid<=1:raise SystemExit('INVALID_WORKER_PID_FILE')
        try:os.kill(pid,0)
        except ProcessLookupError:pass
        else:raise SystemExit('STOP_SANDBOX_WORKER_BEFORE_INSTALL; no files written')
    # The worker takes this same lock around reconciliation and submission.
    lock_path=root/'data/live-observation/hilega-upstox-sandbox-v2/basket-events.jsonl.worker.lock'
    lock_path.parent.mkdir(parents=True,exist_ok=True)
    with lock_path.open('a') as handle:
        fcntl.flock(handle,fcntl.LOCK_EX|fcntl.LOCK_NB)
        for relative in FILES:
            if digest(root/relative) not in {ORIGINALS[relative],HASHES[relative]}:
                raise SystemExit('SOURCE_CHANGED_NO_FILES_WRITTEN:'+relative)
        backup=root/'backups'/('sandbox-lifecycle-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
        backup.mkdir(parents=True)
        installed=[];created=[]
        try:
            for relative,content in FILES.items():
                target=root/relative
                if digest(target)==HASHES[relative]:continue
                if target.exists():
                    old=backup/relative;old.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,old)
                else:created.append(relative)
                target.parent.mkdir(parents=True,exist_ok=True)
                temporary=target.with_name(target.name+'.lifecycle.tmp')
                with temporary.open('w',encoding='utf-8') as stream:
                    stream.write(content);stream.flush();os.fsync(stream.fileno())
                os.replace(temporary,target);installed.append(relative)
        except BaseException:
            for relative in reversed(installed):
                if (backup/relative).exists():shutil.copy2(backup/relative,root/relative)
                elif relative in created:(root/relative).unlink(missing_ok=True)
            raise
        (backup/'created-files.json').write_text(json.dumps(created,indent=2))
    print(json.dumps(dict(status='APPLIED',backup=str(backup),services_started=False,
                         orders_sent=False,timeout_default_seconds=60,tests_run=False)))

if __name__=='__main__':main()
